<script setup lang="ts">
import{ref,onMounted}from'vue';import{api}from'../api';import{statusMeta}from'../utils/status';const clusters=ref<any[]>([]),nodes=ref<any[]>([]),selected=ref<any>();const pick=async(row:any)=>{selected.value=row;nodes.value=await api.get(`/clusters/${row.id}/nodes`)};onMounted(async()=>{clusters.value=await api.get('/clusters');if(clusters.value[0])pick(clusters.value[0])})
</script>
<template><div class="grid" style="grid-template-columns:1fr 1.5fr"><div class="panel"><div class="panel-title"><h3>计算集群</h3><span class="muted">{{clusters.length}} 个集群</span></div><el-table :data="clusters" highlight-current-row @current-change="pick"><el-table-column prop="name" label="集群"><template #default="s"><b>{{s.row.name}}</b><div class="muted">{{s.row.code}} · {{s.row.region}}</div></template></el-table-column><el-table-column prop="gpuTotal" label="GPU" width="80"/><el-table-column label="状态" width="85"><template #default="s"><el-tag :type="statusMeta(s.row.status).type">{{statusMeta(s.row.status).label}}</el-tag></template></el-table-column></el-table></div><div class="panel"><div class="panel-title"><h3>{{selected?.name||'节点列表'}}</h3><span class="muted">资源调度视图</span></div><el-table :data="nodes"><el-table-column prop="name" label="节点"/><el-table-column prop="gpuModel" label="GPU 型号"/><el-table-column label="GPU 分配"><template #default="s">{{s.row.gpuAllocated}} / {{s.row.gpuTotal}}</template></el-table-column><el-table-column label="CPU / 内存"><template #default="s">{{s.row.cpuCores}} C / {{s.row.memoryGb}} GB</template></el-table-column><el-table-column prop="status" label="状态"><template #default><el-tag type="success">就绪</el-tag></template></el-table-column></el-table></div></div></template>
